"""Commisioning"""
import os
import traceback
import json
from builtins import str
from taf.ul.trs_e2e_fw.lib.ems.nom.nom_base import NomBase
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class Commissioning(NomBase):
    """Commisioning"""
    def __init__(self):
        super(Commissioning, self).__init__()

    def configuration_manage(self, **kwargs):
        """Configure Manage"""
        plan = None
        config_manage_param = get_config_variable(["configuration_manage", kwargs.get("plan_name", "iv_fw_plan")])
        # kwargs = {**kwargs, **config_manage_param}
        kwargs |= config_manage_param
        delete_plan = kwargs.pop('delete_plan', True)
        should_provision = kwargs.pop('should_provision', True)
        conf_id = kwargs.pop("conf_id", 1)
        kwargs.pop('operation')  # This is not required for nom. Hence popping operations from argument,
        # otherwise we might see failure if user passes Operation from testcase
        try:
            plan = self.create_plan(**kwargs)
            self._add_mocs_params_to_plan(conf_id, **kwargs)
            if should_provision:
                self.provision_plan(**kwargs)
        except Exception as err:
            logger.debug(traceback.print_exc())
            raise err
        finally:
            if delete_plan and plan is not None:
                self.delete_plan(**kwargs)

    def configuration_get(self, **kwargs):
        """Get configuration"""
        distname = [kwargs.get('dist_name', self.bts_moc_id)]
        conf_id = kwargs.get('conf_id', 1)

        managed_obj_parameters = self.nom_factory.nom.get_managed_objects_parameters(conf_id=conf_id, mo_ids=distname)
        return managed_obj_parameters

    def provision_plan(self, **kwargs):
        """Provision plan"""
        plan_name = kwargs.get('plan_name', 'iv_fw_plan')
        rollback_plan_generation = kwargs.get('rollback_plan_generation', False)
        timeout = kwargs.get('timeout', 10)

        return self.nom_factory.nom.provision_plan(plan_name=plan_name, rollback_plan_generation=rollback_plan_generation, timeout=timeout)

    def _add_mocs_params_to_plan(self, conf_id, **kwargs):
        delta_file = kwargs['config']

        if delta_file:
            delta_json_data = self._load_delta_file_into_dict(delta_file)
            # for item, moc_details in list(delta_json_data.items()):
            for moc_details in delta_json_data:
                self._operate_managed_object(moc_details, conf_id)

    def _load_delta_file_into_dict(self, delta_file):
        delta_file_dir = get_config_variable(['delta_files'])
        delta_full_path = os.path.join(delta_file_dir, delta_file)
        # delta_json_data = {}
        with open(delta_full_path, "r") as file_handle:
            delta_json_data = json.load(file_handle)
        # delta_json_data = get_config_variable([], delta_json_data)
        logger.debug('delta_file_content:\n{}'.format(str(delta_json_data)))
        return delta_json_data

    def plan(self, **kwargs):
        """Plan"""
        operation = kwargs.get('operation')
        # pop the parameters to avoiding errorring out, as it is necessary for netact
        kwargs.pop('ignore_errors', "")
        plan = None
        if operation.lower() == 'create':
            plan = self.create_plan(**kwargs)
        elif operation.lower() == 'get' or operation.lower() == 'delete':
            plan = self.delete_plan(**kwargs)
        return plan

    def create_plan(self, **kwargs):
        """Create Plan"""
        plan_name = kwargs.get('plan_name', 'iv_fw_plan')
        plan_description = kwargs.pop('plan_description', plan_name)
        plan_type = kwargs.get('plan_type', 'ACTUAL')
        timeout = kwargs.get('timeout', 60)
        plan_header = None

        try:
            plan_header = self.nom_factory.nom.create_empty_plan(name=plan_name, description=plan_description, plan_type=plan_type, timeout=timeout)
        except Exception as create_e:
            logger.debug("Create plan failed because:{}".format(str(create_e)))
        return plan_header

    def delete_plan(self, **kwargs):
        """delete Plan using a regex of plan name"""
        plan_type = kwargs.get('plan_type', 'ACTUAL')
        timeout = kwargs.get('timeout', 60)
        plan_dict = None
        before = kwargs.get('before', '')
        plan_name_regex = kwargs.get("plan_name", "iv_fw_plan")
        try:
            plan_dict = self.nom_factory.nom.remove_plans(plan_type=plan_type, before=before, plan_name_regex=plan_name_regex, timeout=timeout)
        except Exception as create_e:
            logger.debug("Create plan failed because:{}".format(str(create_e)))
        return plan_dict

    def _operate_managed_object(self, moc_details, conf_id):
        operation = moc_details['operation']
        moc_dist_name = [moc_details['dist_name']]
        logger.debug('create_managed_object args: {} {}'.format(moc_dist_name, operation))
        if operation.upper() == 'DELETE':
            self.nom_factory.nom.delete_managed_objects(conf_id, moc_dist_name)
        else:
            self.nom_factory.nom.add_managed_objects(conf_id, moc_dist_name)
